<template>
    <section class="group-panel" aria-labelledby="device-groups-title">
        <header class="group-header"><div><h2 id="device-groups-title">{{ $gettext('分组与计划') }}</h2><p>{{ $gettext('把需要相同安排的设备放在一起，一次设置联网、速度、路线、时段或流量额度。') }}</p></div><div class="header-actions"><button type="button" @click="editGlobal">{{ $gettext('默认规则') }}</button><button type="button" class="primary" @click="startCreate">{{ $gettext('新建分组') }}</button></div></header>
        <PageState v-if="loading" kind="loading" :title="$gettext('正在读取设备分组')" />
        <PageState v-else-if="error" kind="error" :title="$gettext('设备分组读取失败')" :description="error" :action-label="$gettext('重新加载')" @action="load" />
        <template v-else>
            <div class="evaluation"><span>{{ $gettext('按路由器时间执行') }} · {{ timezone || '—' }}</span><span>{{ $gettext('下次检查') }} {{ formatDate(nextEvaluationAt) }}</span></div>
            <div v-if="lastBatch && lastBatch.status !== 'unchanged'" class="batch-result" :class="lastBatch.status" role="status"><strong>{{ batchTitle(lastBatch.status) }}</strong><span>{{ $gettext('成功') }} {{ lastBatch.applied }} · {{ $gettext('跳过') }} {{ lastBatch.skipped }} · {{ $gettext('失败') }} {{ lastBatch.failed }}</span></div>
            <PageState v-if="!groups.length && !editing" kind="empty" :title="$gettext('还没有设备分组')" :description="$gettext('例如创建“儿童设备”，设置晚间暂停联网和每月流量额度。')" />
            <div v-else class="group-grid">
                <article v-for="group in groups" :key="group.id" class="group-card"><div class="group-card-title"><div><strong>{{ group.name }}</strong><span>{{ group.members.length }} {{ $gettext('台设备') }}</span></div><span class="priority">P{{ group.priority }}</span></div><p>{{ policySummary(group.policy) }}</p><div class="member-preview">{{ memberSummary(group.members) }}</div><div class="card-actions"><button type="button" @click="startEdit(group)">{{ $gettext('编辑') }}</button><button type="button" class="danger-link" @click="removeGroup(group)">{{ $gettext('删除') }}</button></div></article>
            </div>

            <details v-if="effective.length" class="effective-explanation"><summary>{{ $gettext('查看最终生效结果与来源') }} <small>{{ Math.min(effective.length,50) }} / {{ effective.length }}</small></summary><div class="effective-list"><div v-for="item in effective.slice(0,50)" :key="item.deviceId"><span><strong>{{ deviceName(item.deviceId) }}</strong><small>{{ effectiveSummary(item) }}</small></span><em>{{ sourceSummary(item.sources) }}</em></div></div></details>

            <form v-if="editing" class="editor" @submit.prevent="requestPreview">
                <div class="editor-heading"><div><h3>{{ editingGlobal ? $gettext('默认规则') : editingExisting ? $gettext('编辑分组') : $gettext('新建分组') }}</h3><p>{{ editingGlobal ? $gettext('只为没有更具体规则的设备提供默认值。') : $gettext('单设备例外始终优先；多个分组冲突时，优先级较高的生效。') }}</p></div><button type="button" class="close" @click="cancelEdit" :aria-label="$gettext('关闭')">×</button></div>
                <div v-if="!editingGlobal" class="form-grid"><label><span>{{ $gettext('分组名称') }}</span><input v-model.trim="draft.name" maxlength="64" required :placeholder="$gettext('例如：儿童设备')" /></label></div>
                <details v-if="!editingGlobal" class="advanced-group"><summary>{{ $gettext('高级设置') }}</summary><label><span>{{ $gettext('优先级') }}</span><input v-model.number="draft.priority" type="number" min="0" max="999" /><small>{{ $gettext('单设备例外始终优先；多个分组冲突时，优先级较高的生效。') }}</small></label></details>
                <fieldset v-if="!editingGlobal"><legend>{{ $gettext('选择设备') }} <small>{{ $gettext('已选择') }} {{ draft.members.length }} {{ $gettext('台设备') }}</small></legend><input v-model.trim="deviceQuery" class="device-search" type="search" :placeholder="$gettext('搜索名称、IP 或 MAC')" /><div class="device-options"><label v-for="device in filteredDevices" :key="device.deviceId"><input v-model="draft.members" type="checkbox" :value="device.deviceId" /><span><strong>{{ device.displayName || device.hostname || $gettext('未命名设备') }}</strong><small>{{ device.ipv4?.[0] || device.mac || device.deviceId }}</small></span><em v-if="hasDeviceOverride(device.deviceId)">{{ $gettext('有单设备例外') }}</em></label></div></fieldset>
                <fieldset><legend>{{ $gettext('共同规则') }}</legend><div class="rules-grid">
                    <label><span>{{ $gettext('联网权限') }}</span><select v-model="draft.access"><option value="inherit">{{ $gettext('不设置') }}</option><option value="allow">{{ $gettext('允许联网') }}</option><option value="block">{{ $gettext('暂停联网') }}</option></select></label>
                    <label><span>{{ $gettext('上网路线') }}</span><select v-model="draft.targetId"><option value="">{{ $gettext('不设置') }}</option><option v-for="target in targets" :key="target.id" :value="target.id" :disabled="!target.supported">{{ gatewayTargetLabel(target) }}{{ target.supported ? '' : $gettext('（不可用）') }}</option></select></label>
                    <label class="check"><input v-model="draft.speedEnabled" type="checkbox" />{{ $gettext('速度上限') }}</label><div v-if="draft.speedEnabled" class="inline-fields"><label><span>{{ $gettext('上传 Mbit/s') }}</span><input v-model.number="draft.upload" type="number" min="1" /></label><label><span>{{ $gettext('下载 Mbit/s') }}</span><input v-model.number="draft.download" type="number" min="1" /></label></div>
                    <label class="check"><input v-model="draft.quotaEnabled" type="checkbox" />{{ $gettext('流量额度') }}</label><div v-if="draft.quotaEnabled" class="inline-fields quota"><label><span>{{ $gettext('周期') }}</span><select v-model="draft.quotaPeriod"><option value="daily">{{ $gettext('每天') }}</option><option value="weekly">{{ $gettext('每周') }}</option><option value="monthly">{{ $gettext('每月') }}</option></select></label><label><span>{{ $gettext('额度 GB') }}</span><input v-model.number="draft.quotaGB" type="number" min="0.1" step="0.1" /></label><label><span>{{ $gettext('达到后') }}</span><select v-model="draft.quotaAction"><option value="notify">{{ $gettext('仅提醒') }}</option><option value="block">{{ $gettext('暂停联网') }}</option></select></label></div>
                </div></fieldset>
                <fieldset>
                    <legend>{{ $gettext('休息时段') }}</legend>
                    <label class="check">
                        <input v-model="draft.scheduleEnabled" type="checkbox" />
                        {{ scheduleToggleLabel }}
                    </label>
                    <div v-if="draft.scheduleEnabled" class="schedule-box"><div class="days"><label v-for="day in dayOptions" :key="day.value" :class="{selected:draft.days.includes(day.value)}"><input v-model="draft.days" type="checkbox" :value="day.value" />{{ day.label }}</label></div><div class="inline-fields"><label><span>{{ $gettext('开始') }}</span><input v-model="draft.start" type="time" /></label><label><span>{{ $gettext('结束') }}</span><input v-model="draft.end" type="time" /></label></div><small>{{ $gettext('结束时间早于开始时间时，会自动跨到第二天。') }}</small></div>
                </fieldset>
                <div v-if="previewing" class="preview-card" role="dialog" :aria-label="$gettext('保存前预览')"><strong>{{ $gettext('确认这次调整') }}</strong><span v-if="!editingGlobal">{{ $gettext('影响设备') }}：{{ draft.members.length }}</span><span>{{ previewSummary }}</span><p v-if="overrideCount">{{ overrideCount }} {{ $gettext('台设备有单设备例外，最终值仍以例外为准。') }}</p><div><button type="button" @click="previewing=false">{{ $gettext('返回修改') }}</button><button type="button" class="primary" :disabled="saving" @click="save">{{ saving ? $gettext('正在应用…') : $gettext('确认并应用') }}</button></div></div>
                <p v-if="feedback" class="feedback error">{{ feedback }}</p><div v-if="!previewing" class="editor-actions"><button type="button" @click="cancelEdit">{{ $gettext('取消') }}</button><button class="primary" type="submit">{{ $gettext('预览影响') }}</button></div>
            </form>
        </template>
    </section>
</template>

<script setup lang="ts">
import { computed, reactive, ref } from 'vue'
import { useGettext } from '/@/plugins/i18n'
import request from '/@/request'
import PageState from './components/pageState.vue'
const { $gettext } = useGettext()
const scheduleToggleLabel = $gettext('在指定时段暂停联网')
const loading=ref(true),saving=ref(false),error=ref(''),feedback=ref(''),version=ref(''),timezone=ref(''),nextEvaluationAt=ref(''),editing=ref(false),editingExisting=ref(false),editingGlobal=ref(false),deviceQuery=ref(''),previewing=ref(false)
const groups=ref<any[]>([]),devices=ref<any[]>([]),effective=ref<any[]>([]),targets=ref<any[]>([]),lastBatch=ref<any>()
const blank=()=>({id:'',name:'',priority:10,access:'inherit',members:[] as string[],targetId:'',speedEnabled:false,upload:100,download:1000,quotaEnabled:false,quotaPeriod:'monthly',quotaGB:10,quotaAction:'notify',scheduleEnabled:false,days:[1,2,3,4,5] as number[],start:'22:00',end:'07:00'})
const draft=reactive(blank())
const dayOptions=computed(()=>[{value:1,label:$gettext('一')},{value:2,label:$gettext('二')},{value:3,label:$gettext('三')},{value:4,label:$gettext('四')},{value:5,label:$gettext('五')},{value:6,label:$gettext('六')},{value:0,label:$gettext('日')}])
const filteredDevices=computed(()=>{const needle=deviceQuery.value.toLowerCase();return devices.value.filter(device=>!needle||[device.displayName,device.hostname,device.mac,...(device.ipv4||[])].some(value=>String(value||'').toLowerCase().includes(needle)))})
const minutes=(value:string)=>{const [h,m]=value.split(':').map(Number);return h*60+m};const clock=(value:number)=>`${String(Math.floor(value/60)).padStart(2,'0')}:${String(value%60).padStart(2,'0')}`
const formatDate=(value:string)=>value?new Date(value).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'}):'—'
const deviceName=(id:string)=>{const device=devices.value.find(item=>item.deviceId===id);return device?.displayName||device?.hostname||id}
const gatewayTargetLabel=(target:any)=>{if(target.kind==='default'||target.name==='跟随网络默认')return $gettext('默认路线');if(target.kind==='self'&&target.name==='本机路由')return $gettext('本机路由');if(target.kind==='bypass'&&target.name==='旁路由')return $gettext('旁路由');if(target.kind==='floating'&&target.name==='浮动网关')return $gettext('浮动网关');if(target.name==='自定义网关')return $gettext('自定义网关');return target.name}
const memberSummary=(ids:string[])=>ids.slice(0,3).map(deviceName).join('、')+(ids.length>3?` +${ids.length-3}`:'')||$gettext('尚未选择设备')
const hasDeviceOverride=(id:string)=>effective.value.find(item=>item.deviceId===id)?.sources?.includes('device')
const overrideCount=computed(()=>draft.members.filter(hasDeviceOverride).length)
const sourceSummary=(sources:string[]=[])=>sources.slice(1).map(source=>source==='global'?$gettext('默认规则'):source==='device'?$gettext('单设备例外'):source.startsWith('group:')?(groups.value.find(item=>item.id===source.slice(6))?.name||$gettext('设备分组')):source).join(' → ')||$gettext('系统默认')
const effectiveSummary=(item:any)=>{const values=[item.networkAccess?$gettext('允许联网'):$gettext('暂停联网')];if(item.speed?.enabled)values.push($gettext('已限速'));if(item.targetId&&item.targetId!=='default')values.push($gettext('已指定路线'));if(item.quota?.enabled)values.push($gettext('有流量额度'));return values.join(' · ')}
const policySummary=(policy:any)=>{const values=[] as string[];if(policy?.access===false)values.push($gettext('暂停联网'));else if(policy?.access===true)values.push($gettext('允许联网'));if(policy?.speed?.enabled)values.push($gettext('速度上限'));if(policy?.targetId)values.push($gettext('指定路线'));if(policy?.quota?.enabled)values.push($gettext('流量额度'));if(policy?.schedules?.length)values.push(`${$gettext('休息时段')} ${clock(policy.schedules[0].startMinute)}–${clock(policy.schedules[0].endMinute)}`);return values.join(' · ')||$gettext('仅分组，不覆盖设备设置')}
const previewSummary=computed(()=>policySummary(buildPolicy()))
const batchTitle=(status:string)=>({all_success:$gettext('批量规则已应用'),partial:$gettext('部分设备需要处理'),failed:$gettext('批量规则未应用')} as Record<string,string>)[status]||$gettext('批量检查完成')
const reset=()=>Object.assign(draft,blank())
const startCreate=()=>{reset();editing.value=true;editingExisting.value=false;editingGlobal.value=false;previewing.value=false;feedback.value=''}
const editGlobal=()=>{reset();applyPolicyToDraft(currentGlobal.value);editing.value=true;editingGlobal.value=true;editingExisting.value=false;previewing.value=false}
const currentGlobal=ref<any>(null)
const applyPolicyToDraft=(policy:any)=>{if(!policy)return;draft.access=policy.access===true?'allow':policy.access===false?'block':'inherit';draft.targetId=policy.targetId||'';draft.speedEnabled=Boolean(policy.speed?.enabled);draft.upload=policy.speed?.uploadSpeed||100;draft.download=policy.speed?.downloadSpeed||1000;draft.quotaEnabled=Boolean(policy.quota?.enabled);draft.quotaPeriod=policy.quota?.period||'monthly';draft.quotaGB=policy.quota?.limitBytes?policy.quota.limitBytes/1073741824:10;draft.quotaAction=policy.quota?.action||'notify';const schedule=policy.schedules?.[0];draft.scheduleEnabled=Boolean(schedule);if(schedule){draft.days=[...schedule.days];draft.start=clock(schedule.startMinute);draft.end=clock(schedule.endMinute)}}
const startEdit=(group:any)=>{reset();Object.assign(draft,{id:group.id,name:group.name,priority:group.priority,members:[...group.members]});applyPolicyToDraft(group.policy);editing.value=true;editingExisting.value=true;editingGlobal.value=false;previewing.value=false;feedback.value=''}
const cancelEdit=()=>{editing.value=false;previewing.value=false;feedback.value=''}
const requestPreview=()=>{feedback.value='';if(!editingGlobal.value&&!draft.name)return;if(draft.scheduleEnabled&&!draft.days.length){feedback.value=$gettext('请至少选择一天');return}previewing.value=true}
const buildPolicy=()=>{const access=draft.access==='inherit'?undefined:draft.access==='allow';const schedules=draft.scheduleEnabled?[{id:'rest',enabled:true,days:[...draft.days],startMinute:minutes(draft.start),endMinute:minutes(draft.end),action:'block'}]:[];return{access,targetId:draft.targetId||undefined,speed:draft.speedEnabled?{enabled:true,uploadSpeed:draft.upload,downloadSpeed:draft.download}:undefined,quota:draft.quotaEnabled?{enabled:true,period:draft.quotaPeriod,limitBytes:Math.round(draft.quotaGB*1073741824),action:draft.quotaAction}:undefined,schedules}}
const save=async()=>{saving.value=true;feedback.value='';try{const body=editingGlobal.value?{action:'set_global_policy',expectedVersion:version.value,globalPolicy:buildPolicy()}:{action:'upsert_group',expectedVersion:version.value,group:{id:draft.id||`group_${Date.now().toString(36)}`,name:draft.name,priority:draft.priority,members:[...draft.members],policy:buildPolicy()}};const result=(await request.DeviceMangement.deviceGroupsV2.POST(body)).data.result;if(result?.error)throw new Error(result.error.message);editing.value=false;previewing.value=false;await load()}catch(reason:any){feedback.value=reason?.message||$gettext('保存失败')}finally{saving.value=false}}
const removeGroup=async(group:any)=>{if(!window.confirm(`${$gettext('删除分组')}“${group.name}”？\n${$gettext('设备和单设备例外不会被删除。')}`))return;try{const result=(await request.DeviceMangement.deviceGroupsV2.POST({action:'delete_group',groupId:group.id,expectedVersion:version.value})).data.result;if(result?.error)throw new Error(result.error.message);await load()}catch(reason:any){error.value=reason?.message||$gettext('删除失败')}}
const load=async()=>{loading.value=true;error.value='';try{const [groupResponse,inventoryResponse,targetResponse]=await Promise.all([request.DeviceMangement.deviceGroupsV2.GET(),request.DeviceMangement.deviceInventoryV2.GET(),request.DeviceMangement.gatewayTargetsV2.GET().catch(()=>null)]);const result=groupResponse.data.result;if(result?.error)throw new Error(result.error.message);groups.value=result?.groups||[];currentGlobal.value=result?.globalPolicy||null;effective.value=result?.effective||[];version.value=result?.version||'';timezone.value=result?.timezone||'';nextEvaluationAt.value=result?.nextEvaluationAt||'';lastBatch.value=result?.lastBatch;devices.value=inventoryResponse.data.result?.devices||[];targets.value=targetResponse?.data?.result?.targets||[]}catch(reason:any){error.value=reason?.message||$gettext('读取设备分组失败')}finally{loading.value=false}}
load()
</script>

<style lang="scss" scoped>
.group-panel{color:var(--tit-color)}.group-panel h2,.group-panel h3{margin:0;padding:0;color:inherit;background:none!important;text-align:left}.group-panel h2{font-size:20px}.group-header,.editor-heading,.group-card-title,.card-actions,.editor-actions,.header-actions{display:flex;justify-content:space-between;gap:10px;align-items:flex-start}.group-header p,.editor-heading p{margin:5px 0 0;opacity:.65}.group-panel button{min-height:34px;padding:6px 11px;color:inherit;background:transparent;border:1px solid rgba(127,127,127,.25);border-radius:7px;cursor:pointer}.group-panel .primary{color:#fff;background:#553afe;border-color:#553afe}.evaluation,.batch-result{display:flex;justify-content:space-between;gap:10px;margin:13px 0;padding:9px 11px;background:rgba(127,127,127,.05);border-radius:8px;font-size:12px}.batch-result.all_success{color:#176b45;background:rgba(38,162,105,.1)}.batch-result.partial,.batch-result.failed{color:#9b3b16;background:#fff1e8}.group-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:10px}.group-card{padding:13px;border:1px solid rgba(127,127,127,.15);border-radius:9px}.group-card-title>div{display:grid;gap:3px}.group-card-title span,.member-preview{opacity:.62;font-size:12px}.priority{padding:3px 6px;background:rgba(85,58,254,.1);border-radius:999px}.member-preview{min-height:30px}.card-actions{justify-content:flex-end;margin-top:9px}.danger-link{color:#a13c3c!important}.effective-explanation{margin-top:13px;padding:10px;border:1px solid rgba(127,127,127,.15);border-radius:8px}.effective-explanation summary{min-height:40px;color:#553afe;cursor:pointer;font-weight:600}.effective-list{display:grid;gap:6px;margin-top:9px}.effective-list>div{display:flex;justify-content:space-between;gap:10px;padding:7px;background:rgba(127,127,127,.04);border-radius:6px}.effective-list span{display:grid}.effective-list small{opacity:.62}.effective-list em{max-width:45%;opacity:.7;font-style:normal;text-align:right}.editor{margin-top:14px;padding:15px;border:1px solid rgba(85,58,254,.2);border-radius:10px}.close{border:0!important;font-size:20px}.form-grid,.rules-grid,.inline-fields{display:grid;grid-template-columns:2fr 1fr;gap:9px}.form-grid{grid-template-columns:1fr}.advanced-group{margin:10px 0;padding:0 10px 10px;border:1px solid rgba(127,127,127,.17);border-radius:8px}.advanced-group summary{display:flex;align-items:center;min-height:40px;color:#553afe;cursor:pointer}.editor label{display:grid;gap:5px;font-size:12px}.editor input:not([type=checkbox]),.editor select{box-sizing:border-box;width:100%;min-width:0;min-height:36px;padding:7px 9px;color:inherit;background:transparent;border:1px solid rgba(127,127,127,.25);border-radius:7px}.editor fieldset{margin:12px 0;padding:11px;border:1px solid rgba(127,127,127,.17);border-radius:8px}.editor legend{padding:0 5px;font-weight:600}.device-search{margin-bottom:8px}.device-options{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:6px;max-height:200px;overflow:auto}.device-options label{position:relative;display:flex;align-items:center;gap:8px;padding:7px;border-radius:7px}.device-options span{display:grid;min-width:0}.device-options small{overflow:hidden;opacity:.6;text-overflow:ellipsis}.device-options em{margin-left:auto;color:#9b3b16;font-size:10px;font-style:normal}.check{display:flex!important;align-items:center;gap:7px;min-height:40px}.inline-fields{grid-column:1/-1}.inline-fields.quota{grid-template-columns:repeat(3,1fr)}.days{display:flex;flex-wrap:wrap;gap:6px;margin-bottom:9px}.days label{padding:5px 9px;border:1px solid rgba(127,127,127,.2);border-radius:999px;cursor:pointer}.days label.selected{color:#553afe;background:rgba(85,58,254,.08)}.days input{position:absolute;opacity:0}.schedule-box small{opacity:.62}.preview-card{display:grid;gap:7px;padding:12px;color:inherit;background:rgba(85,58,254,.06);border:1px solid rgba(85,58,254,.16);border-radius:9px}.preview-card p{margin:0;color:#9b3b16}.preview-card>div{display:flex;justify-content:flex-end;gap:8px}.editor-actions{justify-content:flex-end}.feedback{padding:8px;border-radius:7px}.feedback.error{color:#9b3b16;background:#fff1e8}button:focus-visible,input:focus-visible,select:focus-visible,summary:focus-visible{outline:2px solid #553afe;outline-offset:2px}
@media(max-width:640px){.group-header{flex-direction:column}.header-actions{width:100%}.header-actions button{flex:1}.evaluation,.effective-list>div{flex-direction:column}.effective-list em{max-width:none;text-align:left}.form-grid,.rules-grid,.inline-fields,.inline-fields.quota{grid-template-columns:1fr}.device-options{grid-template-columns:1fr}.editor{padding:12px}}
</style>
